
import { BottomSheetInfoContainerStyle, BottomSheetNameContainerStyle, GenDiv } from './index.style'
import { CustomText } from '../../../../../../components'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { BRIEFCASE, DOWNLINE_LV_ICON, EMAIL_ICON, ID_CARD, LIKES_LV_ICON, STAR_LV_ICON, TELEPHONE_BLACK, UPLINE_LV_ICON } from '../../../../../../images'
import moment from 'moment'

function BottomDowwnlineDetail ({getLvDetailData, agentCode, agentName, generation}) {
  const dataIcon = (type, label, value) => {
    const Icon = () => {
      switch (type) {
        case 'recruit':
          return (
            <div className='square-box'>
              {value.charAt(0).toUpperCase()}
            </div>
          )
        case 'id':
          return (
            <div className='square-box'>
              <img src={ID_CARD} alt='id' width={25} />
            </div>
          )
        case 'phone':
          return (
            <div className='square-box'>
              <img src={TELEPHONE_BLACK} alt='id' width={25} />
            </div>
          )
        case 'email':
          return (
            <div className='square-box'>
              <img src={EMAIL_ICON} alt='id' width={25} />
            </div>
          )
        case 'date':
          return (
            <div className='square-box'>
              <img src={BRIEFCASE} alt='id' width={25} />
            </div>
          )
        case 'downline':
          return (
            <div className='square-box'>
              <img src={DOWNLINE_LV_ICON} alt='id' width={25} />
            </div>
          )
        case 'likes':
          return (
            <div className='square-box'>
              <img src={LIKES_LV_ICON} alt='id' width={25} />
            </div>
          )
        case 'upline':
          return (
            <div className='square-box'>
              <img src={UPLINE_LV_ICON} alt='id' width={25} />
            </div>
          )
        case 'star':
          return (
            <div className='square-box'>
              <img src={STAR_LV_ICON} alt='id' width={25} />
            </div>
          )
        default:
          return (
            <div className='square-box'>
              {value.charAt(0).toUpperCase()}
            </div>
          )
      }
    }
    return (
      <div className={`data-container ${type === 'date' || type === 'recruit' ? '' : 'margin-bot'}`}>
        <Icon />
        <div className='data-text'>
          <CustomText
            color={AgentColorPallette.fontGrey}
            weight={500}
            size='14px'

          >
            {label}
          </CustomText>
          <CustomText
            color={AgentColorPallette.black}
            weight={700}
            size='14px'
            bottom='5px'
          >
            {value}
          </CustomText>
        </div>
      </div>)
  }
  
  return (
    <>
      <BottomSheetNameContainerStyle>
        <div>
        <CustomText
          color={AgentColorPallette.black}
          weight={800}
          size='14px'
        >
          {agentName}
        </CustomText>
        <CustomText
          color={AgentColorPallette.black}
          weight={500}
          size='12px'
          bottom='5px'
        >
          {agentCode}
        </CustomText>
        </div>
        <GenDiv>
        <CustomText
          color={AgentColorPallette.white}
          weight={800}
          size='10px'
        >
          Generasi {generation}
        </CustomText>
        </GenDiv>
      </BottomSheetNameContainerStyle>
      <BottomSheetInfoContainerStyle>
        <div className='info-box'>
          <CustomText
            color={AgentColorPallette.black}
            weight={800}
            size='14px'
            bottom='15px'
          >
            Detail {agentName}
          </CustomText>
          {dataIcon('star', 'Mitra Level', getLvDetailData?.agent_title === 'LEADER' ? 'Mitra Bisnis' : getLvDetailData?.agent_title === 'FOUNDER' ? 'Founder' : 'Mitra Eksekutif' )}
          {dataIcon('downline', 'Total Downline', getLvDetailData?.downline_agents_count)}
          {dataIcon('upline', 'Nama Upline', getLvDetailData?.upline_agent_name)}
          {dataIcon('likes', 'Direkrut Oleh', getLvDetailData?.recruited_by_name)}
        </div>
        <div className='info-box'>
          <CustomText
            color={AgentColorPallette.black}
            weight={800}
            size='14px'
            bottom='15px'
          >
            Profil {agentName}
          </CustomText>
          {dataIcon('phone', 'Nomer Ponsel',  getLvDetailData?.lv_agent_phone)}
          {dataIcon('email', 'Email',  getLvDetailData?.lv_agent_email)}
          {dataIcon('date', 'Tanggal Bergabung', moment(getLvDetailData?.lv_agent_joining_date).format('DD/MM/YYYY'))}
        </div>
      </BottomSheetInfoContainerStyle>
    </>
  )
}

export default BottomDowwnlineDetail
