function FilterBottomSheet ({
  show, onClose, onSubmit
}) {
  const [checkedIndex, setCheckedIndex] = useState([])
  const [radioIndex, setRadioIndex] = useState()
  const [formValues, setFormValues] = useState({ categories: [], sort: '', year: [], month: [] })
  
  const checkBox = (index) => {
    const isChecked = checkedIndex.includes(index);
    setCheckedIndex(prevChecked => {
      if (isChecked) {
        return prevChecked.filter(item => item !== index)
      } else {
        return [...prevChecked, index]
      }
    })
    setFormValues(prevValues => ({
      ...prevValues,
      categories: isChecked
        ? prevValues.categories.filter(item => item !== getCheckBoxNames[index].value) 
        : [...prevValues.categories, getCheckBoxNames[index].value],
    }))
  }
  
  const handleRadioClick = (index) => {
    const isChecked = index === radioIndex
    setRadioIndex(isChecked ? null : index)
    setFormValues(prevValues => ({
      ...prevValues,
      sort: isChecked ? '' : getRadioNames[index].value
    }))
  }

  const renderCheckBoxComp = (list, title) => {
    return (
      <CheckBoxComp>
        <CustomText
          color={AgentColorPallette.black}
          size='15px'
          weight={600}
          padLeft='10px'
          paddingTop='10px'
        >
          {title}
        </CustomText>
        {list.map((item, index) => (
          <CheckBoxName key={index}>
            <Row gap='10px' justify='space-between'>
              <CustomText
                color={checkedIndex.includes(index) ? AgentColorPallette.black : AgentColorPallette.borderGrey}
                size='15px'
                weight={600}
              >
                {item.name}
              </CustomText>
              <CustomCheckbox
                isChecked={checkedIndex.includes(index)}
                onChange={() => { checkBox(index) }}
                color={AgentColorPallette.borderGrey}
                bgColor={AgentColorPallette.black}
              />
            </Row>
          </CheckBoxName>
        ))}
      </CheckBoxComp>
    )
  }

  const renderRadioComp = (list, title) => {
    return (
      <CheckBoxComp>
        <CustomText
          color={AgentColorPallette.black}
          size='15px'
          weight={600}
          padLeft='10px'
        >
          {title}
        </CustomText>
        {list.map((item, index) => (
          <CheckBoxName key={index}>
            <Row gap='10px' justify='space-between'>
              <CustomText
                color={index === radioIndex ? AgentColorPallette.black : AgentColorPallette.borderGrey}
                size='15px'
                weight={600}
              >
                {item.name}
              </CustomText>
              <RadioBox
                key={index}
                onClick={() => { handleRadioClick(index) }}
                marginRight={10}
              >
                <RadioInput
                  value={item.name}
                  name={item.name}
                  //   aria-checked={(item.title === selected) || (item.title === selectedData.scale)}
                  onChange={() => { handleRadioClick(index) }}
                  checked={index === radioIndex}
                />
                <Fill />
              </RadioBox>
            </Row>
          </CheckBoxName>
        ))}
      </CheckBoxComp>
    )
  }

  const handleSubmit = (onSubmit) => {
    const finalValue = {
      ...formValues,
      categories: formValues.categories.join(','),
      year: formValues.year?.map(String).join(','),
      month: formValues.month?.map(String).join(',')
    }
    onSubmit(finalValue)
    onClose()
  }

  return (
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
      backGroundColor={AgentColorPallette.darkYellow}
      title={LANG_STRINGS.arrangement}
      maxHeight={'90%'}
      showHeader
    >
      {renderCheckBoxComp(getCheckBoxNames, 'Kategori')}
      {renderRadioComp(getRadioNames, 'Urutkan')}
      <CustomText
        color={AgentColorPallette.black}
        size='15px'
        weight={600}
        padLeft='20px'
        paddingTop='10px'
      >
        {'Periode'}
      </CustomText>
      <AutoSearchBottomSheet
        title=''
        name='year'
        data={getYear}
        displayKey='year'
        dataKey='year'
        isBoxWithoutIcon
        showHeader
        required
        headerTitle='Tahun'
        designV2
        selectedTitle='Semua Tahun'
        onChange={(value) => {
          setFormValues(formValues => {
            const currentYears = formValues.year || []
            if (value.year === null) {
              return { ...formValues, year: [] }
            }
            const index = currentYears.indexOf(value.year)
            if (index > -1) {
              return { ...formValues, year: currentYears.filter(year => year !== value.year) }
            } else {
              return { ...formValues, year: [...currentYears, value.year] }
            }
          })
        }}
      />
      <AutoSearchBottomSheet
        title=''
        name='month'
        data={getMonth}
        displayKey='month'
        dataKey='value'
        isBoxWithoutIcon
        showHeader
        required
        headerTitle='Bulan'
        designV2
        selectedTitle='Semua Bulan'
        onChange={(value) => {
          setFormValues(formValues => {
            const currentMonth = formValues.month || []
            if (value.value === null) {
              return { ...formValues, month: [] }
            }
            const index = currentMonth.indexOf(value.value)
            if (index > -1) {
              return { ...formValues, month: currentMonth.filter(month => month !== value.value) }
            } else {
              return { ...formValues, month: [...currentMonth, value.value] }
            }
          })
        }}
      />
      <FilterBottomSheetStyle
        marginTop={25}
      >
        <Button
          textColor={AgentColorPallette.black}
          borderRadius='8px'
          onClick={() => handleSubmit(onSubmit)}
          backgroundColor={AgentColorPallette.darkYellow}
          className='btn-border'
        >
          {LANG_STRINGS.save}
        </Button>
      </FilterBottomSheetStyle>
    </BottomActionSheet>
  )
}

export default FilterBottomSheet
