import { MYDOWNLINE_ACTIONS } from './actions'

export const INITIAL_STATE = {

}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case MYDOWNLINE_ACTIONS.GET_DOWNLINE_METRICS:
    case MYDOWNLINE_ACTIONS.GET_DOWNLINE_BONUS:
    case MYDOWNLINE_ACTIONS.GET_AGENT_METRICES:
    case MYDOWNLINE_ACTIONS.GET_UNIT_PREMIUM:
    case MYDOWNLINE_ACTIONS.GET_PERSONAL_PREMIUM:
    case MYDOWNLINE_ACTIONS.GET_GROUP_PREMIUM:
    case MYDOWNLINE_ACTIONS.GET_PERSONAL_LIST_PREMIUM:
    case MYDOWNLINE_ACTIONS.GET_GROUP_LIST_PREMIUM:
    case MYDOWNLINE_ACTIONS.GET_UNIT_LIST_PREMIUM:
    case MYDOWNLINE_ACTIONS.SHARE_REFERRAL_CODE:
    case MYDOWNLINE_ACTIONS.GET_LV_DETAIL:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
