import React, { useState, useEffect, useCallback, useRef } from "react";
import { CalendarGrid, CloseButton, DateInputDisplay, DateInputLabel, DateInputSection, DatePickerContainer, DatePickerHeader, DatePickerTitle, DateValue, DayCell, DaysGrid, EditButton, MonthYearRow, MonthYearSelector, NavArrow, NavigationBar, Option, OptionGrid, PopupContainer, PopupContent, PopupHeader, PopupTitle, SelectorPopup, WeekDay, WeekDaysRow } from "./index.style";
import BottomActionSheet from "../../../../../components/BottomActionSheet";

function DatePicker({show, setShow, popupTitle, startDate, setstartDate, endDate, setendDate, isStartDate, isEndDate, selectedStartDate, setSelectedStartDate, setstartDateCalender, setendDateCalender, editStartDate, setEditStartDate}) {
  const currentDate = new Date();
  
  const parseExistingDate = (dateStr) => {
    if (!dateStr) return null;
    
    const [day, month, year] = dateStr.split('/').map(part => parseInt(part));
    return {
      day: day || null,
      month: month ? month - 1 : currentDate.getMonth(), 
      year: year || currentDate.getFullYear()
    };
  };
  
  const existingDate = isStartDate ? parseExistingDate(startDate) : parseExistingDate(endDate);
  
  const [selectedDate, setSelectedDate] = useState(
    existingDate?.day || (isStartDate ? 1 : currentDate.getDate())
  );
  
  const [viewDate, setViewDate] = useState({
    month: existingDate?.month !== undefined ? existingDate.month : currentDate.getMonth(),
    year: existingDate?.year || currentDate.getFullYear(),
  });
  
  const [showSelector, setShowSelector] = useState(null); // 'month', 'year', or null
  const pickerRef = useRef(null); 
  const selectorRef = useRef(null);
  
  useEffect(() => {
    const formatDefaultDate = (day, month, year) => {
      return `${String(day).padStart(2, "0")}/${String(month + 1).padStart(2, "0")}/${year}`;
    };

    if (isStartDate && !startDate) {
      const firstDayDate = formatDefaultDate(1, currentDate.getMonth(), currentDate.getFullYear());
      setstartDate(firstDayDate);
      setSelectedStartDate(firstDayDate);
    }
    
    if (isEndDate && !endDate) {
      const todayDate = formatDefaultDate(currentDate.getDate(), currentDate.getMonth(), currentDate.getFullYear());
      setendDate(todayDate);
    }
  }, [isStartDate, isEndDate, startDate, endDate]);
  
  useEffect(() => {
    if (show) {
      const dateToUse = isStartDate ? startDate : endDate;
      const parsedDate = parseExistingDate(dateToUse);
      
      if (parsedDate && parsedDate.day) {
        setSelectedDate(parsedDate.day);
        setViewDate({
          month: parsedDate.month,
          year: parsedDate.year
        });
      }
    }
  }, [show, isStartDate, isEndDate, startDate, endDate]);
  
  useEffect(() => {
    function handleClickOutside(event) {
      const isOutsidePicker = pickerRef.current && !pickerRef.current.contains(event.target);
      const isOutsideSelector = selectorRef.current && !selectorRef.current.contains(event.target);
      
      if (showSelector && isOutsideSelector) {
        setShowSelector(null);
        return;
      }
      
      if (!showSelector && isOutsidePicker) {
        setShow(false);
        if (isStartDate) setstartDateCalender(false);
        if (isEndDate) setendDateCalender(false);
      }
    }
  
    if (show) {
      document.addEventListener("mousedown", handleClickOutside);
    } else {
      document.removeEventListener("mousedown", handleClickOutside);
    }
  
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [show, showSelector, isStartDate, isEndDate, setShow, setstartDateCalender, setendDateCalender]);
  
  const months = [
    "Jan", "Feb", "Mar", "Apr", "Mei", "Jun",
    "Jul", "Agu", "Sep", "Okt", "Nov", "Des",
  ]; 
  
  const fullMonths = [
    "Januari", "Februari", "Maret", "April", "Mei", "Juni",
    "Juli", "Agustus", "September", "Oktober", "November", "Desember",
  ]; 
  
  const weekDays = ["S", "S", "R", "K", "J", "S", "M"]; 

  const getFormattedDate = useCallback(() => {
    if (!selectedDate) return "";
    return `${String(selectedDate).padStart(2, "0")}/${String(
      viewDate.month + 1
    ).padStart(2, "0")}/${viewDate.year}`;
  }, [selectedDate, viewDate]);

  useEffect(() => {
    if(selectedDate) {
      const formattedDate = getFormattedDate();
      if(isStartDate) {
        setstartDate(formattedDate);
        setSelectedStartDate(formattedDate);
      }
      if(isEndDate) {
        setendDate(formattedDate);
      }
    }
  }, [getFormattedDate, setstartDate, setendDate, isStartDate, isEndDate, setSelectedStartDate, selectedDate]);

  const getDaysInMonth = (year, month) => {
    return new Date(year, month + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (year, month) => {
    return new Date(year, month, 1).getDay();
  };

  const handlePrevMonth = () => {
    setViewDate((prev) => {
      if (prev.month === 0) {
        return { month: 11, year: prev.year - 1 };
      } else {
        return { ...prev, month: prev.month - 1 };
      }
    });
  };

  const handleNextMonth = () => {
    setViewDate((prev) => {
      if (prev.month === 11) {
        return { month: 0, year: prev.year + 1 };
      } else {
        return { ...prev, month: prev.month + 1 };
      }
    });
  };

  const handleDateSelect = (day) => {
    setSelectedDate(day);
    
    setTimeout(() => {
      setShow(false);
      if (isStartDate) setstartDateCalender(false);
      if (isEndDate) setendDateCalender(false);
    }, 300); 
  };

  const handleStartDateEdit = () => {
    setEditStartDate(true)
  };

  const handleCalender = () => {
    setShow(!show)
    isStartDate && setstartDateCalender(false)
    isEndDate && setendDateCalender(false)
  };

  const toggleSelector = (type) => {
    if (showSelector === type) {
      setShowSelector(null);
    } else {
      setShowSelector(type);
    }
  };

  const handleMonthSelect = (monthIndex) => {
    setViewDate((prev) => ({ ...prev, month: monthIndex }));
    setShowSelector(null);
  };

  const handleYearSelect = (year) => {
    setViewDate((prev) => ({ ...prev, year }));
    setShowSelector('month');
  };

  // Generate array of years (current year - 11 to current year + 1)
  const generateYears = () => {
    const currentYear = new Date().getFullYear();
    const years = [];
    // Generate years from current year down to current year - 11
    for (let i = currentYear; i >= currentYear - 11; i--) {
      years.push(i);
    }
    return years;
  };

  const renderCalendarDays = () => {
    const daysInMonth = getDaysInMonth(viewDate.year, viewDate.month);
    const firstDay = getFirstDayOfMonth(viewDate.year, viewDate.month);

    const days = [];

    // Add empty cells for days before the first day of the month
    for (let i = 0; i < firstDay; i++) {
      days.push(<div key={`empty-${i}`}></div>);
    }

    // Add cells for each day of the month
    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(viewDate.year, viewDate.month, day);
      const isWeekend = date.getDay() === 6;

      days.push(
        <DayCell
          key={day}
          isSelected={selectedDate === day}
          isWeekend={isWeekend}
          onClick={() => handleDateSelect(day)}
        >
          {day}
        </DayCell>
      );
    }

    return days;
  };

  const stopPropagation = (e) => {
    e.stopPropagation();
  };

  return (
    <BottomActionSheet show={show}>
      <DatePickerContainer ref={pickerRef}>
        <DatePickerHeader>
          <DatePickerTitle>{popupTitle}</DatePickerTitle>
          <CloseButton onClick={handleCalender}>
            <i className={'fa fa-times'}/>
          </CloseButton>
        </DatePickerHeader>

        {isEndDate && (
          <DateInputSection>
            <DateInputLabel>Dari Tanggal</DateInputLabel>
            <DateInputDisplay>
              <DateValue>{selectedStartDate}</DateValue>
              <EditButton onClick={handleStartDateEdit}>
                <i className={'fas fa-pen'}/>
              </EditButton>
            </DateInputDisplay>
          </DateInputSection>
        )}

        <NavigationBar>
          <NavArrow onClick={handlePrevMonth}>
            <i className={'fas fa-arrow-left'}/>
          </NavArrow>
          <MonthYearRow>
            <MonthYearSelector onClick={() => toggleSelector("month")}>
              {fullMonths[viewDate.month]}
            </MonthYearSelector>
            <MonthYearSelector onClick={() => toggleSelector("year")}>
              {viewDate.year}
              <i className={'fas fa-angle-down'}/>
            </MonthYearSelector>
          </MonthYearRow>
          <NavArrow onClick={handleNextMonth}>
            <i className={'fas fa-arrow-right'}/>
          </NavArrow>
        </NavigationBar>

        <CalendarGrid>
          <WeekDaysRow>
            {weekDays.map((day, index) => (
              <WeekDay key={index} isWeekend={index === 6}>
                {day}
              </WeekDay>
            ))}
          </WeekDaysRow>

          <DaysGrid>{renderCalendarDays()}</DaysGrid>
        </CalendarGrid>
      </DatePickerContainer>

      {showSelector === "month" && (
        <BottomActionSheet 
          show={showSelector === "month"}
          onCloseSheet={() => setShowSelector(null)}
        >
          <PopupContainer onClick={stopPropagation} ref={selectorRef}>
            <PopupHeader>
              <PopupTitle>Pilih Bulan</PopupTitle>
              <CloseButton onClick={() => setShowSelector(null)}>
                <i className={'fa fa-times'}/>
              </CloseButton>
            </PopupHeader>
            <PopupContent>
              <OptionGrid>
                {months.map((month, index) => (
                  <Option
                    key={index}
                    isActive={viewDate.month === index && month === months[viewDate.month]}
                    onClick={() => handleMonthSelect(index)}
                  >
                    {month}
                  </Option>
                ))}
              </OptionGrid>
            </PopupContent>
          </PopupContainer>
        </BottomActionSheet>
      )}

      {showSelector === "year" && (
        <BottomActionSheet 
          show={showSelector === "year"}
          onCloseSheet={() => setShowSelector(null)}
        >
          <PopupContainer onClick={stopPropagation} ref={selectorRef}>
            <PopupHeader>
              <PopupTitle>Pilih Tahun</PopupTitle>
              <CloseButton onClick={() => setShowSelector(null)}>
                <i className={'fa fa-times'}/>
              </CloseButton>
            </PopupHeader>
            <PopupContent>
              <OptionGrid>
                {generateYears().map((year) => (
                  <Option
                    key={year}
                    isActive={viewDate.year === year}
                    onClick={() => handleYearSelect(year)}
                  >
                    {year}
                  </Option>
                ))}
              </OptionGrid>
            </PopupContent>
          </PopupContainer>
        </BottomActionSheet>
      )}
    </BottomActionSheet>
  );
};

export default DatePicker;