export const getDownlineMetrics = (payload = {}) => ({
  type: MYDOWNLINE_ACTIONS.GET_DOWNLINE_METRICS_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: ConfigUrl.getDownlineAgentMetricsApi
  }
})

