import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useMyDownlineContextValue } from '../../context'
import { getAgentMetrices, getDownlineBonus, getDownlineMetrics, getGroupListPremium, getGroupPremium, getLvDetail, getPersonalListPremium, getPersonalPremium, getUnitListPremium, getUnitPremium, shareReferralCode } from '../actions'

export const useMyDownlineServiceCall = (actionsCall = () => {}) => {
  const [myState, dispatch] = useMyDownlineContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])

  return [myState, request]
}

export const useGetDownlineMetrics = () => {
  return useMyDownlineServiceCall(getDownlineMetrics)
}

export const useGetAgentMetrices = () => {
  return useMyDownlineServiceCall(getAgentMetrices)
}

