import { Error, Grid, Row } from '../../../../commonStyle/index.style'
import { SELECTION_ARROW } from '../../../../images'
import { AutoSearchStyleSheet, SearchListStyle, SearchBoxItemStyle } from './index.style'
import { LANG_STRINGS } from '../../../../lang/index'
import BottomActionSheet from '../../../BottomActionSheet'
import { useState, useCallback, useMemo, forwardRef, useEffect } from 'react'
import { Button, CustomText } from '../../..'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { createPortal } from 'react-dom'
import CustomCheckbox from '../../../CustomCheckbox'
import { FilterBottomSheetStyle, Selectedtitle } from '../../../../containers/Private/Downline/component/FilterBottomSheet/index.style'

function AutoSearchBottomSheet ({
  title, required, data, name, displayKey, dataKey,
  children, onRenderList, defaultValue = {}, error, isHideField,
  isIconWithBox, isBoxWithoutIcon, onChange = () => { }, onCloseSheet, showHeader = false, headerTitle, disabled = false, designV2 = false, selectedTitle
}, parentRef) {
  const [show, setShow] = useState(false || isHideField)
  const [query, setQuery] = useState('')
  const [selected, setSelected] = useState((defaultValue && defaultValue[dataKey]) || [])
  const [displayValue, setDisplayValue] = useState((defaultValue && defaultValue[displayKey]) || '')
  const list = useMemo(() => {
    return (data && data.filter(item => {
      const value = typeof item === 'string' ? item : item[displayKey]
      return `${value}`.toLowerCase().indexOf(query.toLowerCase()) !== -1
    })) || []
  }, [data, displayKey, query])

  useEffect(() => {
    if (!selected && defaultValue) {
      setSelected(defaultValue[dataKey])
      setDisplayValue(defaultValue[displayKey])
    }
  }, [defaultValue, selected, displayKey, dataKey])

  const handleCloseSheet = useCallback(() => {
    if (isHideField && onCloseSheet) {
      onCloseSheet()
    }
    setShow(false)
    setQuery('')
  }, [onCloseSheet, isHideField])

  const handleSelected = useCallback((item) => {
    setSelected(prevSelected => {
      if (prevSelected.includes(item[dataKey])) {
        return prevSelected.filter(selectedItem => selectedItem !== item[dataKey])
      } else {
        return [...prevSelected, item[dataKey]]
      }
    })
    setDisplayValue(prevDisplay => {
      const newDisplay = selected.includes(item[dataKey])
        ? prevDisplay.split(', ').filter(value => value !== item[displayKey]).join(', ')
        : prevDisplay ? `${prevDisplay}, ${item[displayKey]}` : item[displayKey]
      return newDisplay
    })
    setQuery('')
    onChange(item)
  }, [dataKey, displayKey, onChange, selected])

  const handleSelectAll = useCallback(() => {
    dataKey === 'value' ? onChange({ value: null }) : onChange({ year: null });
    if (selected.length === data.length) {
      setSelected([])
      setDisplayValue('')
    } else {
      const allSelected = data.map(item => item[dataKey])
      allSelected.forEach(element => {
        onChange({ value: element })
        onChange({ year: element })
      })
      setSelected(allSelected)
      setDisplayValue(data.map(item => item[displayKey]).join(', '))
    }
  }, [data, selected, displayKey, dataKey, onChange])

  const allSelected = selected.length === data.length

  const renderMultipleSelectComp = () => {
    if (onRenderList) {
      return onRenderList(list)
    }

    return list.map((item) => {
      if (isIconWithBox || isBoxWithoutIcon) {
        return (
          <SearchBoxItemStyle
            key={item[dataKey]}
            isBoxWithoutIcon
          >
            <Row gap='10px' justify='space-between'>
              <CustomText
                weight={600}
                size={isBoxWithoutIcon ? '0.85em' : '0.65em'}
                color={AgentColorPallette.darkCharcoal}
                textAlign='center'
                bottom='0'
                top='4px'
                padRight='30px'
              >
                {item[displayKey]}
              </CustomText>
              <CustomCheckbox
                isChecked={selected.includes(item[dataKey])}
                onChange={() => handleSelected(item)}
                color={AgentColorPallette.borderGrey}
                bgColor={AgentColorPallette.black}
              />
            </Row>
          </SearchBoxItemStyle>
        )
      }
      return (
        <div
          className={`search-list-item ${(selected === item[dataKey]) && 'selected-active'}`}
          key={item[dataKey]}
          onClick={() => handleSelected(item)}
        >
          {item[displayKey]}
        </div>
      )
    })
  }

  return (
    <AutoSearchStyleSheet error={error}>
      {!isHideField && (
        <>
          {
            !designV2 ?
              <div className='auto-input-box'>
                <Grid
                  gridColumn='1fr 14px'
                  gridGap='0.9rem'
                  onClick={() => setShow(true)}
                  className='auto-search-input'
                >
                  <div className='autocomplete-text'>
                    {displayValue || LANG_STRINGS.select}
                  </div>
                  <div>
                    <img src={SELECTION_ARROW} alt='' />
                  </div>
                </Grid>
                {
                  error && <Error>{error}</Error>
                }
              </div> :
              <Row
                className='search-type-input auto-input-box'
                justify='space-between'
                align='center'
                onClick={() => setShow(true)}
                disabled={disabled}
              >
                <CustomText
                  color={AgentColorPallette.black}
                  size='12px'
                >
                  {displayValue || selectedTitle}
                </CustomText>
                <img src={SELECTION_ARROW} alt='' />
              </Row>
          }
        </>)}
      {
        show && createPortal(
          <BottomActionSheet
            show={show}
            onCloseSheet={handleCloseSheet}
            zIndex={5}
            showHeader={showHeader}
            title={headerTitle}
            backGroundColor
          >
            <Selectedtitle>
              <Row gap='10px' justify='space-between'>
                <CustomText
                  color={AgentColorPallette.black}
                  size='15px'
                  weight={600}
                >
                  {selectedTitle}
                </CustomText>
                <CustomCheckbox
                  isChecked={allSelected} 
                  onChange={handleSelectAll}
                  color={AgentColorPallette.borderGrey}
                  bgColor={AgentColorPallette.black}
                />
              </Row>
            </Selectedtitle>
            <SearchListStyle>
              <div
                className={((isIconWithBox || isBoxWithoutIcon) && list.length) ? 'search-container-list-icon' : 'search-container-list'}
              >
                {renderMultipleSelectComp()}
              </div>
            </SearchListStyle>
            <FilterBottomSheetStyle>
              <Button
                textColor={AgentColorPallette.black}
                borderRadius='8px'
                onClick={handleCloseSheet}
                backgroundColor={AgentColorPallette.darkYellow}
                className='btn-border'
              >
                {LANG_STRINGS.save}
              </Button>
            </FilterBottomSheetStyle>
          </BottomActionSheet>,
          document.getElementById('bottom-sheet-portal')
        )
      }
    </AutoSearchStyleSheet>
  )
}

export default forwardRef(AutoSearchBottomSheet)
