import BottomActionSheet from '../../../../../components/BottomActionSheet'
import { Box1, ButtonPadding, ButtonPadding2, DesText, Image, Image1, ShareQuotationDiv, ShareQuotationStyle, Text, Text1, ToggleButton, Top } from './index.style'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../lang/index'
import { Button, CustomText, } from '../../../../../components'
import { useCallback, useEffect, useRef, useState } from 'react'
import CircularLoader from '../../../../../components/CircularLoader'
import { useHistory, useParams } from 'react-router'
import { CLOSE_BLACK_ICON, SENT_LV_ICON, SHARE_LV_GOLDEN_ICON
} from '../../../../../images'
import { copySharingData } from '../../../../../helpers/utility'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { APP_HOST } from '../../../../../configs/url'
import { regex } from '../../../../../constants/regex'
import DynamicFormV3 from '../../../../../components/DynamicFormV3'

import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { useShareReferralCode } from '../../state/hooks/useMyDownlineState'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useUpdateGlobal } from '../../../../../state/globalState/hooks/useGlobalContext'

export const getShareQuotationWithCustomerTravel = () => ({
  fieldData: [
    {
      label: 'Nama Pelanggan',
      type: 'input',
      name: 'name',
      required: true,
    },
    {
      label: 'Nomor Ponsel',
      type: 'input',
      name: 'mobile_no',
      required: true,
      validator: (value = '') => {
        if (!(['+62', '62', '08'].some((pre) => value.startsWith(pre)))) return ERROR_LANG.phoneNumberNotStartsWith62
        if (value.startsWith('+62') && value.length > 15) return ERROR_LANG.max15DigitAllowed
        if (value.length > 14) return ERROR_LANG.max14DigitAllowed
        if (!regex.phoneRegex.test(value)) return ERROR_LANG.phoneNumberError
      }
    },
    {
      label: 'Email',
      type: 'input',
      name: 'email',
      required: true,
      validator: (value = '') => {
        if (!regex.emailRegex.test(value)) {
          return ERROR_LANG.emailRequiredError
        }
        return ''
      }
    }
  ]
})

function ShareReferralPopup({ show, onClose }) {
  const formRef = useRef()
  const { id, draftId } = useParams()
  const history = useHistory()
  const [{ agentDetails }] = useUpdateGlobal()
  const [userBlurred, setUserBlurred] = useState(true)
  const [formValues, setFormValues] = useState({ name: '', email: '', mobile_no: '' })
  const [showShareDetailPopup, setShowShareDetailPopup] = useState(false)
  const [isActive, setIsActive] = useState(false);
  const [{ shareReferralCodeData }, shareReferralCodeReq] = useShareReferralCode()
  const [{ SHARE_REFERRAL_CODE_REQUEST_LOADER }] = useLoaderContextValue()

  const renderSentIcon = useCallback((icon, text) => {
    return (
      <Top >
        <Image1 src={icon} alt={text} />
      </Top>
    )
  }, [])

  const body = {
    customer_data: {
      email: formValues.email,
      mobile_no: formValues.mobile_no,
      name: formValues.name,
    },
    draft_id: id ? id : draftId
  }

  const allFilled = Object.values(formValues).every(Boolean);

  const handleCustomerForm = (name, value) => {
    setFormValues({
      ...formValues,
      [name]: value,
    })
  }

  const handleSendQuote = async () => {
    try {
      const response = await shareReferralCodeReq({
        body: {
          customer_name: formValues.name, 
          phone_no: formValues.mobile_no,
          email: formValues.email,
          referral_code: agentDetails?.referral_code,
          channel: 'both'
        }
      })
      if (response?.error) {
        throw new Error(response.error)
      }
      setShowShareDetailPopup(true)
    } catch (error) {
      ShowSnackbar.error({
        visible: true,
        text: error.message || 'Failed to share referral code'
      })
    }
  }

  const handleCopyReferralCode = () => {
    navigator.clipboard.writeText(agentDetails?.referral_code);
    setIsActive(true);
    ShowSnackbar.success({
      visible: true,
      text: 'Referral code copied to clipboard'
    });
  }

  const getSharingData = (source) => {
    const linkOfShare = `${APP_HOST}/extended_warranty/draft/policy/${id || draftId}/?source=${source}`
    return {
      link: linkOfShare
    }
  }

  const handleCopyLink = () => {
    const sharingDate = getSharingData('quotation_copy')
    copySharingData(sharingDate.link)
    ShowSnackbar.success({
      visible: true,
      text: 'Menyalin ke clipboard berhasil'
    })
  }

  const handleNewPolicy = () => {
    history.push({
      pathname: `/extended_warranty`
    })
  }

  const handleBackHome = () => {
    history.push({
      pathname: `/dashboard`
    })
  }

  return (
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
      zIndex={4}
      backGroundColor
    >
      {!showShareDetailPopup && (
        <>
          <ShareQuotationStyle>
            <div className='close-cross'>
              <img src={CLOSE_BLACK_ICON} alt='' className='img-width' onClick={onClose} />
            </div>
            <Box1>
              <div className='box-adjust box-content'>
                {
                  renderSentIcon(
                    SHARE_LV_GOLDEN_ICON,
                  )
                }
              </div>
            </Box1>
            <CustomText
              color={AgentColorPallette.darkCharcoal}
              weight={700}
              size='15px'
              textAlign='center'
            >
              {'Kode Referral Saya'}
            </CustomText>
            <CustomText
              color={AgentColorPallette.ppBlue}
              weight={800}
              size='20px'
              textAlign='center'
            >
              {agentDetails?.referral_code}
            </CustomText>
            <ButtonPadding2>
                <ToggleButton
                active={isActive} onClick={handleCopyReferralCode}
                >
                {isActive ? "Tersalin" : "Salin"}
                </ToggleButton>
            </ButtonPadding2>
            <CustomText
              color={AgentColorPallette.darkCharcoal}
              weight={600}
              size='12px'
              textAlign='center'
              marginBottom='15px'
            >
              {'Isi data dibawah untuk mengirimkan kode referral Anda.'}
            </CustomText>
            <CircularLoader isLoading={SHARE_REFERRAL_CODE_REQUEST_LOADER}>
              <DynamicFormV3
                formData={getShareQuotationWithCustomerTravel()}
                onChange={handleCustomerForm}
                ref={formRef}
                values={formValues}
                setUserBlurred={setUserBlurred}
              />
            </CircularLoader>
          </ShareQuotationStyle>
          <ButtonPadding>
            <Button
              onClick={handleSendQuote}
              textColor={'black'}
              borderRadius={'10px'}
              disabled={!allFilled}
            >
              {LANG_STRINGS.share}
            </Button>
          </ButtonPadding>
        </>
      )
      }
      {showShareDetailPopup && (
        <>
          <ShareQuotationDiv>
            <div className='close-cross'>
              <img src={CLOSE_BLACK_ICON} alt='' className='img-width' onClick={onClose} />
            </div>
            <Box1>
              <div className='box-adjust box-content'>
                {
                  renderSentIcon(
                    SENT_LV_ICON,
                  )
                }
              </div>
            </Box1>
            <CustomText
              color={AgentColorPallette.darkCharcoal}
              weight={800}
              size='15px'
              textAlign='center'
            >
              {'Kode Referral Terkirim'}
            </CustomText>
            <DesText>
            <CustomText
              color={AgentColorPallette.fontDarkerGrey}
              weight={600}
              size='12px'
              textAlign='center'
            >
              {'Kode referral telah berhasil terkirim. Silakan cek'}
            </CustomText>
            <CustomText
              color={AgentColorPallette.fontDarkerGrey}
              weight={600}
              size='12px'
              textAlign='center'
            >
              {'WhatsApp dan Email yang dituju.'}
            </CustomText>
            </DesText>
          </ShareQuotationDiv>
          <ButtonPadding>
            <Button
              textColor={'black'}
              borderRadius={'10px'}
              onClick={onClose}
            >
              Tutup
            </Button>
          </ButtonPadding>
        </>
      )
      }
    </BottomActionSheet>
  )
}

export default ShareReferralPopup
