import { createContext, useContext, useReducer } from 'react'

export const MyDownlineContext = createContext()

export const MyDownlineContextProvider = ({ reducer, ...props }) => {
  return (
    <MyDownlineContext.Provider value={useReducer(reducer, {})}>
      {props.children}
    </MyDownlineContext.Provider>
  )
}

export const useMyDownlineContextValue = () => useContext(MyDownlineContext)
